style.css:
@-moz-document domain("classroom.google.com") {
:root {
    
    --my-cream: #faf5ed;
    --my-paper: #fffaf3;
    --my-latte: #eee0cf;
    --my-caramel: #c49a72;
    --my-brown: #947052;
    --my-dark: #574334;
    --my-cinnamon: #b97859;
    --my-terracotta: #cf9276;
    --my-muted: #aa9581;
  }

  
  html,
  body {
    background: var(--my-cream) !important;
    color: var(--my-dark) !important;
  }

  
  body {
    font-family: "Avenir Next", "Segoe UI", sans-serif !important;
  }

  
  a {
    color: var(--my-cinnamon) !important;
  }

  
  img {
    border-radius: 12px !important;
  }

  
  ::selection {
    background: var(--my-latte) !important;
    color: var(--my-dark) !important;
  }

  
  ::-webkit-scrollbar {
    width: 9px !important;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--my-caramel) !important;
    border-radius: 20px !important;
  }

  ::-webkit-scrollbar-track {
    background: var(--my-cream) !important;
  }
  


@-moz-document domain("classroom.google.com") {

  
  .wBE4bf {
    background-color: #fffaf3 !important;
    background: #fffaf3 !important;
    border: 1px solid #ead9c6 !important;
    border-radius: 18px !important;
    overflow: hidden !important;
  }

  
  .wBE4bf h2 {
    color: #76563f !important;
  }

  
  .wBE4bf .google-symbols {
    color: #b97859 !important;
  }

}
}
